package com.example.starter.cutover.domain;

import java.util.EnumSet;
import java.util.Set;

/**
 * 割接申请状态机。
 *
 * <pre>
 * CREATED -> ANALYZED -> APPROVED -> EXECUTING -> VERIFIED -> SEALED
 *                    \\-> REJECTED       \\-> ROLLED_BACK / WINDOW_OVERDUE
 * </pre>
 */
public enum ApplicationStatus {

    /** 已申请，待影响分析。 */
    CREATED,
    /** 已完成影响分析，待审批。 */
    ANALYZED,
    /** 审批通过，窗口已占用。 */
    APPROVED,
    /** 审批拒绝（优先级抢占或窗口冲突）。 */
    REJECTED,
    /** 窗口执行中。 */
    EXECUTING,
    /** 全部步骤与关键验证点通过。 */
    VERIFIED,
    /** 封板，终态。 */
    SEALED,
    /** 已回退，终态。 */
    ROLLED_BACK,
    /** 窗口超期并强制回退，终态（回退类终态）。 */
    WINDOW_OVERDUE;

    private static final Set<ApplicationStatus> TERMINAL =
            EnumSet.of(SEALED, ROLLED_BACK, WINDOW_OVERDUE, REJECTED);

    /** 已占用窗口、对其他申请构成冲突的状态。 */
    private static final Set<ApplicationStatus> WINDOW_HOLDING =
            EnumSet.of(APPROVED, EXECUTING, VERIFIED, SEALED);

    public boolean isTerminal() {
        return TERMINAL.contains(this);
    }

    public boolean isWindowHolding() {
        return WINDOW_HOLDING.contains(this);
    }
}

package com.example.starter.cutover.domain;

/**
 * 步骤状态：PENDING 待执行 -> RUNNING 执行中 -> DONE 完成 / FAILED 失败；
 * 回退指令下达后，未完成步骤在同一事务内冻结为 FROZEN。
 */
public enum StepStatus {

    PENDING,
    RUNNING,
    DONE,
    FAILED,
    FROZEN
}

package com.example.starter.cutover.domain;

/**
 * 步骤类型：VERIFY 为关键验证点，适用 10 分钟超时与硬性检查回退判据。
 */
public enum StepType {

    NORMAL,
    VERIFY
}

package com.example.starter.cutover.domain;

/**
 * 回退判据命中类型，写入 rollback_record.trigger_reason，可复算。
 */
public enum RollbackReason {

    /** 关键验证点超时（自步骤开始起算，恰满 10 分钟未通过即命中）。 */
    VERIFY_TIMEOUT,
    /** 关键验证点硬性检查失败。 */
    HARD_CHECK_FAILED,
    /** 普通步骤执行失败。 */
    STEP_FAILED,
    /** 窗口结束仍有未完成步骤，转窗口超期并强制回退。 */
    WINDOW_OVERDUE,
    /** 人工/系统强制回退。 */
    FORCED
}

package com.example.starter.cutover.domain;

/**
 * 步骤回报阶段：START 开始执行；RESULT 回报执行结果。
 */
public enum ReportPhase {

    START,
    RESULT
}

package com.example.starter.cutover.domain;

/**
 * 步骤回报结果：SUCCESS 通过；FAIL 普通失败；HARD_FAIL 硬性检查失败。
 */
public enum ReportResult {

    SUCCESS,
    FAIL,
    HARD_FAIL
}

