 * 回退指令下达后，未完成步骤在同一事务内冻结为 FROZEN。
 */
public enum StepStatus {

    PENDING,
    RUNNING,
    DONE,
    FAILED,
    FROZEN
}

package com.example.starter.cutover.domain;

/**
 * 步骤类型：VERIFY 为关键验证点，适用 10 分钟超时与硬性检查回退判据。
 */
public enum StepType {

    NORMAL,
    VERIFY
}

package com.example.starter.cutover.domain;

/**
 * 回退判据命中类型，写入 rollback_record.trigger_reason，可复算。
 */
public enum RollbackReason {

    /** 关键验证点超时（自步骤开始起算，恰满 10 分钟未通过即命中）。 */
    VERIFY_TIMEOUT,
    /** 关键验证点硬性检查失败。 */
    HARD_CHECK_FAILED,
    /** 普通步骤执行失败。 */
    STEP_FAILED,
    /** 窗口结束仍有未完成步骤，转窗口超期并强制回退。 */
    WINDOW_OVERDUE,
    /** 人工/系统强制回退。 */
    FORCED
}

package com.example.starter.cutover.domain;

/**
 * 步骤回报阶段：START 开始执行；RESULT 回报执行结果。
 */
public enum ReportPhase {

    START,
    RESULT
}

package com.example.starter.cutover.domain;

/**
 * 步骤回报结果：SUCCESS 通过；FAIL 普通失败；HARD_FAIL 硬性检查失败。
 */
public enum ReportResult {

    SUCCESS,
    FAIL,
    HARD_FAIL
}

