package com.example.starter.cutover.repository;

import com.example.starter.cutover.domain.StepStatus;
import com.example.starter.cutover.po.StepPO;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 割接步骤数据访问。
 */
@Repository
public class StepRepository {

    private static final RowMapper<StepPO> MAPPER = (rs, rowNum) -> {
        StepPO po = new StepPO();
        po.setId(rs.getLong("id"));
        po.setCutoverId(rs.getLong("cutover_id"));
        po.setSeq(rs.getInt("seq"));
        po.setName(rs.getString("name"));
        po.setStepType(rs.getString("step_type"));
        po.setStatus(rs.getString("status"));
        Timestamp started = rs.getTimestamp("started_at");
        po.setStartedAt(started == null ? null : started.toLocalDateTime());
        Timestamp completed = rs.getTimestamp("completed_at");
        po.setCompletedAt(completed == null ? null : completed.toLocalDateTime());
        return po;
    };

    private final JdbcTemplate jdbcTemplate;

    public StepRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public long insert(StepPO po) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbcTemplate.update(connection -> {
            PreparedStatement ps = connection.prepareStatement(
                    "INSERT INTO cutover_step "
                            + "(cutover_id, seq, name, step_type, status, started_at, completed_at) "
                            + "VALUES (?,?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setLong(1, po.getCutoverId());
            ps.setInt(2, po.getSeq());
            ps.setString(3, po.getName());
            ps.setString(4, po.getStepType());
            ps.setString(5, po.getStatus());
            ps.setTimestamp(6, po.getStartedAt() == null ? null : Timestamp.valueOf(po.getStartedAt()));
            ps.setTimestamp(7, po.getCompletedAt() == null ? null : Timestamp.valueOf(po.getCompletedAt()));
            return ps;
        }, keyHolder);
        long id = keyHolder.getKey().longValue();
        po.setId(id);
        return id;
    }

    public List<StepPO> findByCutoverId(long cutoverId) {
        return jdbcTemplate.query(
                "SELECT * FROM cutover_step WHERE cutover_id = ? ORDER BY seq",
                MAPPER, cutoverId);
    }

    /**
     * 条件更新单步骤状态，返回是否命中；用于回报与冻结之间的行级竞争。
     */
    public boolean compareAndUpdateStatus(long stepId, List<StepStatus> expected, StepStatus target,
                                          LocalDateTime startedAt, LocalDateTime completedAt) {
        String placeholders = String.join(",", expected.stream().map(s -> "?").toList());
        StringBuilder sql = new StringBuilder("UPDATE cutover_step SET status = ?");
        if (startedAt != null) {
            sql.append(", started_at = ?");
        }
        if (completedAt != null) {
            sql.append(", completed_at = ?");
        }
        sql.append(" WHERE id = ? AND status IN (").append(placeholders).append(")");
        List<Object> params = new java.util.ArrayList<>();
        params.add(target.name());
        if (startedAt != null) {
            params.add(Timestamp.valueOf(startedAt));
        }
        if (completedAt != null) {
            params.add(Timestamp.valueOf(completedAt));
        }
        params.add(stepId);
        expected.forEach(s -> params.add(s.name()));
        return jdbcTemplate.update(sql.toString(), params.toArray()) == 1;
    }

    /**
     * 将割接下全部未完成步骤（PENDING/RUNNING）冻结为 FROZEN，返回受影响行数。
     */
    public int freezeUnfinished(long cutoverId) {
        return jdbcTemplate.update(
                "UPDATE cutover_step SET status = 'FROZEN' "
                        + "WHERE cutover_id = ? AND status IN ('PENDING','RUNNING')",
                cutoverId);
    }
}

package com.example.starter.cutover.repository;

import com.example.starter.cutover.po.RollbackRecordPO;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

/**
 * 回退记录数据访问；cutover_id 上有唯一约束，保证同一割接最多一条回退指令。
 */
@Repository
public class RollbackRecordRepository {

    private static final RowMapper<RollbackRecordPO> MAPPER = (rs, rowNum) -> {
        RollbackRecordPO po = new RollbackRecordPO();
        po.setId(rs.getLong("id"));
        po.setCutoverId(rs.getLong("cutover_id"));
        po.setTriggerReason(rs.getString("trigger_reason"));
        po.setDetail(rs.getString("detail"));
        long stepId = rs.getLong("step_id");
        po.setStepId(rs.wasNull() ? null : stepId);
        po.setSnapshotJson(rs.getString("snapshot_json"));
        po.setRolledBackAt(rs.getTimestamp("rolled_back_at").toLocalDateTime());
        return po;
    };

    private final JdbcTemplate jdbcTemplate;

    public RollbackRecordRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 插入回退记录；唯一约束冲突时抛出 {@link DuplicateKeyException}，由业务层据此放弃回退。
     */
    public long insert(RollbackRecordPO po) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbcTemplate.update(connection -> {
            PreparedStatement ps = connection.prepareStatement(
                    "INSERT INTO rollback_record "
                            + "(cutover_id, trigger_reason, detail, step_id, snapshot_json, rolled_back_at) "
                            + "VALUES (?,?,?,?,?,?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setLong(1, po.getCutoverId());
            ps.setString(2, po.getTriggerReason());
            ps.setString(3, po.getDetail());
            if (po.getStepId() == null) {
                ps.setNull(4, java.sql.Types.BIGINT);
            } else {
                ps.setLong(4, po.getStepId());
            }
            ps.setString(5, po.getSnapshotJson());
            ps.setTimestamp(6, Timestamp.valueOf(po.getRolledBackAt()));
            return ps;
        }, keyHolder);
        long id = keyHolder.getKey().longValue();
        po.setId(id);
        return id;
    }

    public Optional<RollbackRecordPO> findByCutoverId(long cutoverId) {
        List<RollbackRecordPO> list = jdbcTemplate.query(
                "SELECT * FROM rollback_record WHERE cutover_id = ?", MAPPER, cutoverId);
        return list.stream().findFirst();
    }
}

package com.example.starter.cutover.repository;

import com.example.starter.cutover.po.IdempotencyRecordPO;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 幂等记录数据访问；(request_id, scope) 唯一约束保证并发重放下只有一条记录。
 */
@Repository
public class IdempotencyRepository {

    private static final RowMapper<IdempotencyRecordPO> MAPPER = (rs, rowNum) -> {
        IdempotencyRecordPO po = new IdempotencyRecordPO();
        po.setId(rs.getLong("id"));
        po.setRequestId(rs.getString("request_id"));
        po.setScope(rs.getString("scope"));
        po.setFingerprint(rs.getString("fingerprint"));
        po.setResourceId(rs.getString("resource_id"));
        po.setCreatedAt(rs.getTimestamp("created_at").toLocalDateTime());
        return po;
    };

    private final JdbcTemplate jdbcTemplate;

    public IdempotencyRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public Optional<IdempotencyRecordPO> find(String requestId, String scope) {
        List<IdempotencyRecordPO> list = jdbcTemplate.query(
                "SELECT * FROM idempotency_record WHERE request_id = ? AND scope = ?",
                MAPPER, requestId, scope);
        return list.stream().findFirst();
    }

    /**
     * 插入幂等记录；唯一约束冲突返回 false（并发重放已被其他事务抢先登记）。
     */
    public boolean tryInsert(String requestId, String scope, String fingerprint,
                             String resourceId, LocalDateTime createdAt) {
        int rows = jdbcTemplate.update(
                "INSERT INTO idempotency_record (request_id, scope, fingerprint, resource_id, created_at) "
                        + "VALUES (?,?,?,?,?)",
                requestId, scope, fingerprint, resourceId, Timestamp.valueOf(createdAt));
        return rows == 1;
    }

    /**
     * 回填首次请求产生的资源标识。
     */
    public void updateResourceId(long id, String resourceId) {
        jdbcTemplate.update("UPDATE idempotency_record SET resource_id = ? WHERE id = ?",
                resourceId, id);
    }
}

