package com.example.starter.cutover.support;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.TreeMap;

/**
 * 幂等指纹工具：将任意请求对象规范化为字段名排序的 JSON，再计算 SHA-256。
 * 指纹覆盖 requestId 与全部业务字段，字段顺序差异不影响指纹。
 */
public final class FingerprintUtil {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private FingerprintUtil() {
    }

    public static String sha256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }

    /**
     * 计算业务对象的规范化指纹。
     */
    public static String fingerprint(Object request) {
        JsonNode normalized = sort(MAPPER.valueToTree(request));
        return sha256(MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(normalized));
    }

    /**
     * 递归按字段名排序对象节点，保证序列化结果稳定。
     */
    private static JsonNode sort(JsonNode node) {
        if (node.isObject()) {
            TreeMap<String, JsonNode> sorted = new TreeMap<>();
            node.fields().forEachRemaining(e -> sorted.put(e.getKey(), sort(e.getValue())));
            return JsonNodeFactory.instance.pojoNode(sorted).isObject()
                    ? MAPPER.valueToTree(sorted)
                    : MAPPER.valueToTree(sorted);
        }
        if (node.isArray()) {
            var array = JsonNodeFactory.instance.arrayNode();
            node.forEach(child -> array.add(sort(child)));
            return array;
        }
        return node;
    }
}

