                .filter(s -> s.getId().equals(r.getStepId()))
                .map(StepPO::getSeq)
                .findFirst().orElse(null);
    }
    return new RollbackRecordView(true, r.getTriggerReason(), r.getDetail(),
            stepSeq, r.getSnapshotJson(), r.getRolledBackAt());
